class Animal {
  constructor(name) {
    this.name = name;
  }
  eat() {
    return this.name + ' eats';
  }
}

class Dog extends Animal {
  constructor(name, breed) {
    super(name);
    this.breed = breed;
  }
  bark() {
    return 'Woof!';
  }
}

const buddy = new Dog('Buddy', 'Golden');
console.log(buddy.name);
console.log(buddy.eat());
console.log(buddy.bark());
